const module={exports:{}};new Function('require','module','exports',built.outputFiles[0].text)(createRequire(import.meta.url),module,module.exports);

const {boundary,newAnonymousSession,PixelDecoder}=module.exports;
const all=[];
globalThis.fetch=async (_url,init)=>{all.push({kind:'outbound',body:JSON.parse(init.body)});return new Response('synthetic failure',{status:503});};
for(const host of ['session','do']){
 const f=boundary(host),g=await newAnonymousSession(f.env,'meridian');
 Object.assign(f.env,{WEBHOOK_ENDPOINTS:JSON.stringify([{name:'synthetic',type:'custom',url:'https://synthetic.invalid/destination',enabled:true,retryConfig:{maxRetries:1,backoffMs:1}}]),EVENT_QUEUE:{send:async body=>all.push({kind:'queue',body})}});
 const event=(subject=g.subject)=>({eventId:'00000000-0000-4000-8000-000000000001',timestamp:1,eventType:'track',source:'synthetic',event:'purchase',user:{userId:subject,anonymousId:subject,email:'synthetic@example.invalid'},consent:{tracking:false}});
 const p=await f.call('/realtime/session/'+g.sessionId+'/preferences',g.capability,{trackingConsent:false,personalizationEnabled:false});if(p.status!==200)throw Error('preference '+p.status);
 const probe=async(label,path,cap,body,cookie)=>{all.length=0;f.sessions.calls.length=0;f.effects.length=0;const r=await f.call(path,cap,body,'meridian',cookie);let result;if(r.headers.get('Content-Type')?.includes('image'))result={bytes:(await r.arrayBuffer()).byteLength};else {const b=await r.json();result={success:b.success,processed:b.processed,dispatchStatus:b.status,trackingEnabled:b.trackingEnabled};}await f.drain();console.log(JSON.stringify({host,label,status:r.status,...result,outbound:all.filter(x=>x.kind==='outbound').length,queued:all.filter(x=>x.kind==='queue').map(x=>x.body.type),containsVictim:JSON.stringify(all).includes('vis-11111111-1111-4111-8111-111111111111'),containsRequestContext:all.some(x=>!!(x.body.event??x.body).page),sessionReads:f.sessions.calls.filter(x=>x.startsWith('get:')).length,shopperCalls:f.effects.filter(x=>x.startsWith('object:')).length}));};
 await probe('owned stored refusal without cookie','/track/event',g.capability,event());
 await probe('unsigned explicit cookie refusal','/track/event',undefined,event(),'opt_tracking_consent=false; opt_personalization_enabled=false');
 await probe('mixed-subject batch despite refusal','/track/batch',g.capability,{events:[event(),event('vis-11111111-1111-4111-8111-111111111111')],consent:{tracking:false}});
 const pixel=new PixelDecoder().encode({recipientId:'vis-11111111-1111-4111-8111-111111111111',emailId:'synthetic@example.invalid'});
 await probe('unsigned pixel with explicit refusal','/pixel/track/'+encodeURIComponent(pixel)+'?trackingConsent=false',undefined,undefined,'opt_tracking_consent=false');
}

